import React, { useEffect, useState } from 'react';
import axios from 'axios';
import { useNavigate } from 'react-router-dom';

function Jobs() {
  const [jobs, setJobs] = useState([]);
  const [loading, setLoading] = useState(true);
  const navigate = useNavigate();

  useEffect(() => {
    fetchJobs();
  }, []);

  const fetchJobs = async () => {
    try {
      const res = await axios.get('http://localhost:5001/api/jobs', { withCredentials: true });
      setJobs(res.data.data);
    } catch (err) {
      console.error(err);
    } finally {
      setLoading(false);
    }
  };

  const handleApply = (jobId) => {
    navigate(`/upload?jobId=${jobId}`);
  };

  return (
    <div className="container mt-5">
      <div className="d-flex justify-content-between align-items-center mb-4">
        <h2>Available Jobs</h2>
        <button className="btn btn-success" onClick={() => navigate('/create-job')}>Post New Job (Recruiter)</button>
      </div>

      {loading ? <p>Loading...</p> : (
        <div className="row">
          {jobs.length === 0 ? <p>No active job postings.</p> : jobs.map(job => (
            <div className="col-md-6 mb-4" key={job._id}>
              <div className="card h-100 shadow-sm">
                <div className="card-body">
                  <h5 className="card-title">{job.title}</h5>
                  <p className="card-text">{job.description}</p>
                  <div>
                    <strong>Skills: </strong>
                    {job.requiredSkills.map((skill, i) => (
                      <span key={i} className="badge bg-secondary me-1">{skill}</span>
                    ))}
                  </div>
                  <button className="btn btn-primary mt-3" onClick={() => handleApply(job._id)}>
                    Apply Now
                  </button>
                </div>
                <div className="card-footer text-muted">
                  Posted on {new Date(job.createdAt).toLocaleDateString()}
                </div>
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

export default Jobs;
